import json
rows=[]
for l in open('776281ae-af46-4fad-992a-5c90e1ea58e7.jsonl'):
    d=json.loads(l)
    m=d.get('message') or {}
    c=m.get('content')
    if isinstance(c,str): rows.append((d.get('timestamp'),m.get('role'),'text',c))
    elif isinstance(c,list):
        for b in c:
            if b.get('type')=='text': rows.append((d.get('timestamp'),m.get('role'),'text',b['text']))
            elif b.get('type')=='tool_use': rows.append((d.get('timestamp'),m.get('role'),'use',b['name']+' '+json.dumps(b['input'])[:600]))
a=[r for r in rows if r[1]=='assistant' and r[2]=='text']
for r in a[-4:]: print(r[0],'\n',r[3],'\n-----')
print("=== last tool uses")
